@sig trait CommunicationEvidenceAssessor_Api {
  def id: Art.BridgeId
  def communication_evidence_Id : Art.PortId
  def communication_assessment_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var communication_assessment: Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment = $

  def put_communication_assessment(value : Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment) : Unit = {
    Contract(
      Modifies(communication_assessment),
      Ensures(
        communication_assessment == value
      )
    )
    Spec {
      communication_assessment = value
    }

    Art.putValue(communication_assessment_Id, Observation_Sortie_Eligibility_Supervisor.SingleEquipmentAssessment_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class CommunicationEvidenceAssessor_Initialization_Api (
  val id: Art.BridgeId,
  val communication_evidence_Id : Art.PortId,
  val communication_assessment_Id : Art.PortId) extends CommunicationEvidenceAssessor_Api

@datatype class CommunicationEvidenceAssessor_Operational_Api (
  val id: Art.BridgeId,
  val communication_evidence_Id : Art.PortId,
  val communication_assessment_Id : Art.PortId) extends CommunicationEvidenceAssessor_Api {

  // Logika spec var representing port state for incoming data port
  @spec var communication_evidence: Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence = $

  def get_communication_evidence() : Option[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence] = {
    Contract(
      Ensures(
        Res == Some(communication_evidence)
      )
    )
    val value : Option[Observation_Sortie_Eligibility_Supervisor.EquipmentEvidence] = Art.getValue(communication_evidence_Id) match {
